<?php
namespace Tests\Feature;
use App\Models\{Owner,User,Venue,MetaConnection};use App\Services\{VenueSettings,ConversationService,MetaMessaging,ChatService};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\{DB,Http};use Illuminate\Support\Str;use Tests\TestCase;
class DesignMessagingTest extends TestCase {
 use RefreshDatabase;
 private function venue():Venue{$u=User::factory()->create();$o=Owner::unguarded(fn()=>Owner::create(['user_id'=>$u->id,'name'=>'Dueño','email'=>$u->email,'password'=>'OwnerPassword12345','activated'=>true,'email_verified_at'=>now()]));return Venue::create(['owner_id'=>$u->id,'owner_account_id'=>$o->id,'slug'=>'local-'.Str::lower(Str::random(8)),'name'=>'Local probado','published'=>true,'settings'=>array_replace(VenueSettings::defaults(),['address'=>'Colima','capacity'=>100,'weekday_price'=>500000,'weekend_price'=>700000,'holiday_price'=>900000,'extra_hour_price'=>100000,'deposit_value'=>30,'open_hour'=>10,'close_hour'=>26,'prep_minutes'=>0,'clean_minutes'=>60,'included_hours'=>8])]);}
 private function connection(Venue $v,string $channel='whatsapp'):MetaConnection{return MetaConnection::create(['venue_id'=>$v->id,'channel'=>$channel,'account_id'=>'12345','enabled'=>true,'auto_reply'=>true,'credentials'=>['app_secret'=>'test-secret','access_token'=>'test-access','verify_token'=>'verify-test-123456789','version'=>'v26.0']]);}
 private function payload(string $id='wamid.test',string $text='Precios',string $account='12345'):array{return ['object'=>'whatsapp_business_account','entry'=>[['changes'=>[['value'=>['metadata'=>['phone_number_id'=>$account],'messages'=>[['id'=>$id,'from'=>'5215555555555','timestamp'=>(string)now()->timestamp,'type'=>'text','text'=>['body'=>$text]]]]]]]]];}
 private function webhook(Venue $v,array $p,bool $valid=true){config(['portal.kind'=>'client']);$raw=json_encode($p);return $this->call('POST','/api/meta/webhooks/'.$v->slug.'/whatsapp',[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_ACCEPT'=>'application/json','HTTP_X_HUB_SIGNATURE_256'=>$valid?'sha256='.hash_hmac('sha256',$raw,'test-secret'):'bad'],$raw);}
 public function test_new_owner_can_register_without_invitation_only_on_owner_portal():void{config(['portal.owner_registration'=>'open']);config(['portal.kind'=>'owner']);$d=['name'=>'Dueño propio','email'=>'own@example.com','password'=>'OwnerPassword12345','password_confirmation'=>'OwnerPassword12345'];$this->postJson('/api/owner-auth/register',$d)->assertCreated();$o=Owner::first();$this->assertTrue($o->activated);$this->assertSame('internal_owner',User::find($o->user_id)->account_type);$this->postJson('/api/owner-auth/register',$d)->assertUnprocessable();$this->postJson('/api/register',$d)->assertForbidden();}
 public function test_self_signup_cannot_claim_a_migrated_owner():void{config(['portal.owner_registration'=>'open']);$v=$this->venue();$v->owner->update(['activated'=>false]);config(['portal.kind'=>'owner']);$this->postJson('/api/owner-auth/register',['name'=>'Intruso','email'=>$v->owner->email,'password'=>'OwnerPassword12345','password_confirmation'=>'OwnerPassword12345'])->assertUnprocessable();$this->assertFalse($v->owner->fresh()->activated);}
 public function test_design_draft_is_private_and_only_published_when_requested():void{$v=$this->venue();$d=app(\App\Http\Controllers\DesignController::class)->defaults();$d['primary']='#123456';$this->actingAs($v->owner)->putJson('/api/owner/venues/'.$v->slug.'/design',$d)->assertOk();$this->getJson('/api/venues/'.$v->slug)->assertJsonPath('design',null)->assertJsonMissingPath('design_draft');$this->putJson('/api/owner/venues/'.$v->slug.'/design',$d+['publish'=>true])->assertOk();$this->getJson('/api/venues/'.$v->slug)->assertJsonPath('design.primary','#123456');$d['primary']='#654321';$this->putJson('/api/owner/venues/'.$v->slug.'/design',$d)->assertOk();$this->getJson('/api/venues/'.$v->slug)->assertJsonPath('design.primary','#123456');}
 public function test_design_and_inbox_are_scoped_to_owner():void{$a=$this->venue();$b=$this->venue();$this->actingAs($b->owner)->getJson('/api/owner/venues/'.$a->slug.'/design')->assertForbidden();$this->getJson('/api/owner/venues/'.$a->slug.'/inbox')->assertForbidden();$this->getJson('/api/owner/venues/'.$a->slug.'/messaging')->assertForbidden();}
 public function test_design_rejects_executable_css():void{$v=$this->venue();$d=app(\App\Http\Controllers\DesignController::class)->defaults();$d['primary']='url(javascript:alert(1))';$this->actingAs($v->owner)->putJson('/api/owner/venues/'.$v->slug.'/design',$d)->assertUnprocessable();}
 public function test_meta_credentials_are_encrypted_and_never_returned():void{$v=$this->venue();$c=$this->connection($v);$this->assertStringNotContainsString('test-secret',$c->getRawOriginal('credentials'));$this->actingAs($v->owner)->getJson('/api/owner/venues/'.$v->slug.'/messaging')->assertOk()->assertJsonMissingPath('0.credentials')->assertDontSee('test-access');$this->getJson('/api/venues/'.$v->slug)->assertDontSee('test-secret');}
 public function test_webhook_verification_and_invalid_signature():void{$v=$this->venue();$this->connection($v);$this->get('/api/meta/webhooks/'.$v->slug.'/whatsapp?hub.mode=subscribe&hub.verify_token=verify-test-123456789&hub.challenge=42')->assertOk()->assertSee('42');$this->webhook($v,$this->payload(),false)->assertUnauthorized();$this->assertSame(0,DB::table('thread_messages')->count());}
 public function test_signed_webhook_is_deduplicated_and_wrong_account_is_ignored():void{$v=$this->venue();$this->connection($v);$this->webhook($v,$this->payload())->assertOk();$this->webhook($v,$this->payload())->assertOk();$this->webhook($v,$this->payload('other','Precios','999'))->assertOk();$this->assertSame(1,DB::table('thread_messages')->count());}
 public function test_meta_worker_sends_grounded_reply_once():void{$v=$this->venue();$this->connection($v);Http::fake(['graph.facebook.com/*'=>Http::response(['messages'=>[['id'=>'out-1']]])]);$this->webhook($v,$this->payload())->assertOk();$meta=app(MetaMessaging::class);$this->assertSame(1,$meta->process());$this->assertSame(0,$meta->process());Http::assertSentCount(1);Http::assertSent(fn($r)=>$r['messaging_product']==='whatsapp'&&str_contains($r['text']['body'],'5,000.00'));$this->assertDatabaseHas('thread_messages',['direction'=>'out','status'=>'sent','topic'=>'prices']);}
 public function test_paused_or_old_conversation_does_not_send():void{$v=$this->venue();$this->connection($v);$this->webhook($v,$this->payload())->assertOk();DB::table('message_threads')->update(['paused'=>true]);Http::fake();app(MetaMessaging::class)->process();Http::assertNothingSent();$this->assertDatabaseHas('thread_messages',['status'=>'stored']);DB::table('message_threads')->update(['paused'=>false]);$old=$this->payload('old');$old['entry'][0]['changes'][0]['value']['messages'][0]['timestamp']=(string)now()->subHours(25)->timestamp;$this->webhook($v,$old);DB::table('message_threads')->update(['last_inbound_at'=>now()->subHours(25)]);app(MetaMessaging::class)->process();Http::assertNothingSent();$this->assertDatabaseHas('thread_messages',['status'=>'outside_window']);}
 public function test_failed_send_is_not_automatically_retried():void{$v=$this->venue();$this->connection($v);Http::fake(['graph.facebook.com/*'=>Http::response([],500)]);$this->webhook($v,$this->payload());$meta=app(MetaMessaging::class);$meta->process();$meta->process();Http::assertSentCount(1);$this->assertDatabaseHas('thread_messages',['direction'=>'out','status'=>'unknown']);}
 public function test_linked_channels_continue_context_and_do_not_expose_other_customer():void{$v=$this->venue();$u=User::factory()->create();$this->actingAs($u);$code=$this->postJson('/api/venues/'.$v->slug.'/conversation-link')->assertOk()->json('code');$c=$this->connection($v);app(MetaMessaging::class)->receive($c,$this->payload('before','Precios'));$social=DB::table('message_threads')->where('channel','whatsapp')->first();$service=app(ConversationService::class);$service->record($social,'out','Tarifas del local','prices','sent');$this->assertTrue($service->link($v,$social,$code));$this->assertFalse($service->link($v,$social,$code));$web=$service->webThread($v,'u:'.$u->id,$u->id);$facts=$service->facts($v,$web,'y fines de semana',app(ChatService::class));$this->assertSame('prices',$facts['topic']);$this->assertSame('location',$service->facts($v,$web,'y ubicación',app(ChatService::class))['topic']);$this->getJson('/api/venues/'.$v->slug.'/conversation-history')->assertSee('Tarifas del local');$this->actingAs(User::factory()->create())->getJson('/api/venues/'.$v->slug.'/conversation-history')->assertJsonCount(0);}
 public function test_link_code_does_not_work_for_another_venue():void{$v=$this->venue();$other=$this->venue();$this->actingAs(User::factory()->create());$code=$this->postJson('/api/venues/'.$v->slug.'/conversation-link')->json('code');$c=$this->connection($other);app(MetaMessaging::class)->receive($c,$this->payload());$t=DB::table('message_threads')->where('venue_id',$other->id)->first();$this->assertFalse(app(ConversationService::class)->link($other,$t,$code));}
 public function test_messenger_and_instagram_payloads_filter_echoes_and_send_correct_api():void{foreach(['instagram','facebook'] as $channel){$v=$this->venue();$c=$this->connection($v,$channel);$payload=['object'=>$channel==='facebook'?'page':'instagram','entry'=>[['id'=>'12345','messaging'=>[['sender'=>['id'=>'67890'],'recipient'=>['id'=>'12345'],'timestamp'=>now()->timestamp*1000,'message'=>['mid'=>'msg-1','text'=>'Horarios']],['sender'=>['id'=>'67890'],'recipient'=>['id'=>'12345'],'timestamp'=>now()->timestamp*1000,'message'=>['mid'=>'echo','text'=>'No','is_echo'=>true]]]]]];app(MetaMessaging::class)->receive($c,$payload);$this->assertSame(1,DB::table('message_threads')->where('venue_id',$v->id)->count());$host=$channel==='instagram'?'graph.instagram.com':'graph.facebook.com';Http::fake([$host.'/*'=>Http::response(['message_id'=>'out-'.$channel])]);$this->assertSame(1,app(MetaMessaging::class)->process());Http::assertSent(fn($r)=>str_contains($r->url(),$host)&&$r['recipient']['id']==='67890');}}
 public function test_web_chat_retains_topic_and_respects_pause():void{$v=$this->venue();$u=User::factory()->create();$this->actingAs($u);$conversation=(string)Str::uuid();$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Precios','conversation'=>$conversation])->assertOk();$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'y fines de semana','conversation'=>$conversation])->assertOk()->assertSee('7,000.00');$this->assertSame(4,DB::table('thread_messages')->count());DB::table('message_threads')->update(['paused'=>true]);$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Precios','conversation'=>$conversation])->assertStatus(423);}
 public function test_expired_link_and_anonymous_history_are_rejected():void{$v=$this->venue();$this->getJson('/api/venues/'.$v->slug.'/conversation-history')->assertUnauthorized();$this->actingAs(User::factory()->create());$code=$this->postJson('/api/venues/'.$v->slug.'/conversation-link')->json('code');DB::table('contact_links')->update(['expires_at'=>now()->subMinute()]);$c=$this->connection($v);app(MetaMessaging::class)->receive($c,$this->payload());$t=DB::table('message_threads')->where('channel','whatsapp')->first();$this->assertFalse(app(ConversationService::class)->link($v,$t,$code));}

}
